Definition incell (c : Z * Z) (a : word) : Prop := fst c <= u a < fst c + snd c.
Definition mframe (cells : list (Z * Z)) (m m' : word -> option byte) : Prop :=
  mem_grows m m' /\ forall a : word, (forall c, In c cells -> ~ incell c a) -> m' a = m a.

